func postToolUses(o observed) (out []map[string]any) {
	for _, h := range o.hooks {
		if h["hook_event_name"] == "postToolUse" {
			out = append(out, map[string]any{"tool": h["tool_name"], "input": h["tool_input"], "output": h["tool_output"]})
		}
	}
