cat >> codex-mock/e2e/001_hooks/posttool_ids_test.go <<'E'

// The recorded run runs/stops: three commands, the first two refused by a
// PreToolUse hook (JSON deny, exit 2), the third allowed.

// A command a before-tool hook refused does not run, so no PostToolUse fires
// for it: the only one is the allowed command's, with its input and output,
// as in the recording.
// sr:proves posttooluse-payload/codex
func TestNoPostToolUseForARefusedCommand(t *testing.T) {
	rec := loadRecording(t, "stops")
	got := replay(t, rec)
	require.Equal(t, 0, got.Code, got.Stderr)

	posted := func(lines []map[string]any) (out []map[string]any) {
		for _, l := range lines {
			if l["hook_event_name"] == "PostToolUse" {
				out = append(out, map[string]any{"input": l["tool_input"], "response": l["tool_response"]})
			}
		}
		return out
	}
	want := posted(jsonLines(readFile(t, filepath.Join(rec.sample, "payloads.jsonl"))))
	require.Equal(t, []map[string]any{{"input": map[string]any{"command": "echo FINE"}, "response": "FINE\n"}}, want)
	assert.Equal(t, want, posted(got.hookLog()))
}
E
cat >> cursor-mock/e2e/001_hooks/posttool_output_test.go <<'E'

// postToolUse names each call (tool_use_id, a different one for each) and
// says how long it took (duration, in milliseconds, more than none for a
// call that ran), and fires only for a call that ran: the call a preToolUse
// hook refused fires postToolUseFailure instead (runs/file-tools,
// runs/pretool-refusal).
// sr:proves posttooluse-payload/cursor
func TestPostToolUseNamesTheCallAndItsDurationAndFiresOnlyForCallsThatRan(t *testing.T) {
	got, want := replay(t, "file-tools")
	ids := map[any]bool{}
	n := 0
	for _, h := range got.raw {
		if h["hook_event_name"] != "postToolUse" {
			continue
		}
		n++
		require.NotEmpty(t, h["tool_use_id"])
		ids[h["tool_use_id"]] = true
		require.Greater(t, h["duration"], 0.0, "a call that ran took some time")
	}
	require.Equal(t, 4, n)
	require.Len(t, ids, n, "a different tool_use_id for each call")
	require.Equal(t, len(postToolUses(want)), n)

	refused, rwant := replay(t, "pretool-refusal")
	require.Equal(t, postToolUses(rwant), postToolUses(refused))
	var commands []any
	for _, p := range postToolUses(refused) {
		commands = append(commands, p["input"].(map[string]any)["command"])
	}
	require.Equal(t, []any{"echo FINE"}, commands, "only the call no hook refused")
}
E
